def solve(payload):
    events, ttl = payload["events"], payload["ttl_s"]
    if ttl <= 0:
        return {"error": "invalid_policy"}
    if any(e["kind"] not in ("issue", "refresh", "revoke", "check") for e in events):
        return {"error": "invalid_kind"}
    if any(e["time_s"] < 0 or (i and e["time_s"] < events[i-1]["time_s"]) for i, e in enumerate(events)):
        return {"error": "time_order"}
    tokens, outcomes = {}, []
    for event in events:
        token, now, kind = event["token"], event["time_s"], event["kind"]
        state = tokens.get(token)
        if kind == "issue":
            tokens[token] = {"expiry": now+ttl, "revoked": False}
            result = "issued"
        elif kind == "refresh":
            if state is not None and not state["revoked"] and now < state["expiry"]:
                state["expiry"] = now+ttl
                result = "refreshed"
            else:
                result = "denied"
        elif kind == "revoke":
            if state is None:
                result = "unknown"
            else:
                state["revoked"] = True
                result = "revoked"
        elif state is None:
            result = "unknown"
        elif state["revoked"]:
            result = "revoked"
        elif now >= state["expiry"]:
            result = "expired"
        else:
            result = "active"
        outcomes.append(result)
    return {"outcomes": outcomes}

